### RevenueChart.tsx
```tsx
import { useEffect, useState } from 'react';

interface ChartData {
  month: string;
  revenue: number;
}

export default function RevenueChart({ data }: { data: number[] }) {
  const [chartData, setChartData] = useState<ChartData[]>([]);

  useEffect(() => {
    const months = [
      'Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun',
      'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'
    ];
    const formattedData = months.map((month, index) => ({
      month,
      revenue: data[index] || 0,
    }));
    setChartData(formattedData);
  }, [data]);

  return (
    <div className="h-64 relative">
      <div className="flex items-end h-full gap-2">
        {chartData.map((item, index) => (
          <div
            key={index}
            className="flex flex-col items-center"
            style={{ width: '6.5%' }}
          >
            <div
              className="bg-gradient-to-t from-accent to-emerald-600 h-16 rounded-t"
              style={{
                height: `${(item.revenue / Math.max(...data)) * 100}%`,
                maxWidth: '100%',
              }}
            ></div>
            <div className="text-xs text-gray-500 mt-1">{item.month}</div>
          </div>
        ))}
      </div>
    </div>
  );
}
```

